import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const blogDirectory = join(process.cwd(), "content", "blog");
const outputPath = join(process.cwd(), "src", "lib", "blog.generated.ts");

if (!existsSync(blogDirectory)) {
  if (existsSync(outputPath)) {
    console.warn(`Skipping blog bundle generation because ${blogDirectory} does not exist.`);
    process.exit(0);
  }

  throw new Error(`Cannot generate blog bundle: ${blogDirectory} does not exist.`);
}

const posts = readdirSync(blogDirectory)
  .filter((filename) => filename.endsWith(".mdx"))
  .sort()
  .map((filename) => ({
    slug: filename.replace(/\.mdx$/, ""),
    raw: readFileSync(join(blogDirectory, filename), "utf-8"),
  }));

const content = `// This file is generated by scripts/generate-blog-bundle.mjs.
// It keeps MDX blog content available in Cloudflare Workers, where runtime fs access is unavailable.

export type BundledBlogPost = {
  slug: string;
  raw: string;
};

export const BUNDLED_BLOG_POSTS = ${JSON.stringify(posts, null, 2)} satisfies BundledBlogPost[];
`;

writeFileSync(outputPath, content);
